import {chanceBags,chanceLessons,chanceQuestions,chanceCopy} from './chance-line-content.mjs';
import {changeChanceLine,chanceLineModel,chanceLineNarration,chancePoint} from './chance-line-core.mjs';
import {hearButton} from './play-media.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['build','Place a chance'],['learn','See why'],['questions','Try questions']];
const button=(action,label,value='',extra='')=>`<button type="button" class="secondary" data-cl-action="${action}" data-cl-value="${esc(value)}" ${extra}>${esc(label)}</button>`;
const bagName=b=>`${b.sun} Sun + ${b.moon} Moon`;
function bagPicture(b){return `<figure class="cl-bag-picture" data-cl-bag="${esc(b.id)}"><div class="cl-counters" aria-hidden="true">${Array.from({length:b.sun+b.moon},(_,i)=>`<span class="cl-counter ${i<b.sun?'cl-sun':'cl-moon'}">${i<b.sun?'☀':'☾'}</span>`).join('')}</div><figcaption><strong>${esc(bagName(b))}</strong><br>${b.sun+b.moon} equal-chance positions in all</figcaption></figure>`;}
function line(rows){return `<div class="cl-line" data-cl-line><div class="cl-axis" aria-hidden="true">${Array.from({length:13},(_,i)=>`<span class="cl-tick" style="left:${i*100/12}%"></span>`).join('')}</div><div class="cl-anchors"><span>0<br>impossible</span><span>1/2<br>even chance</span><span>1<br>certain</span></div>${rows.map(r=>`<div class="cl-pin-row" data-cl-pin-row="${r.kind}"><div class="cl-pin-track" aria-hidden="true"><span class="cl-pin cl-${r.kind}-pin" style="left:${r.index*100/12}%"></span></div><p class="cl-pin-label">${esc(r.label)}</p></div>`).join('')}</div>`;}
const turnControls=(action,index,count,noun)=>`<nav class="cl-actions" aria-label="${noun} navigation">${button(action,`Previous ${noun}`,index-1,index===0?'disabled':'')}<span>${index+1} of ${count}</span>${button(action,`Next ${noun}`,index+1,index===count-1?'disabled':'')}</nav>`;
function build(work,m){const rows=[];if(m.own)rows.push({kind:'own',index:m.own.index,label:`Your pin: ${m.own.label}`});if(m.reference)rows.push({kind:'reference',index:m.reference.index,label:`Reference: ${m.reference.raw}${m.reference.raw===m.reference.label?'':` = ${m.reference.label}`} · ${m.reference.word}`});return `<p>${esc(chanceCopy.buildInstruction)}</p><div class="cl-bench"><section class="cl-bag-station"><div class="cl-bag-chooser"><label for="cl-bag-select">Choose a pictured bag</label><select id="cl-bag-select" data-cl-action="bag">${chanceBags.map((b,i)=>`<option value="${i}"${i===work.bag?' selected':''}>${esc(bagName(b))}</option>`).join('')}</select>${turnControls('bag',work.bag,chanceBags.length,'bag')}</div>${bagPicture(m.bag)}</section><section class="cl-placement" aria-label="Place the chance of Sun"><p class="cl-event"><strong>What is the chance of Sun?</strong></p><label for="cl-point-select">Your point on the chance line</label><select id="cl-point-select" data-cl-action="pin"><option value="" disabled${m.own?'':' selected'}>Choose a point</option>${Array.from({length:13},(_,i)=>`<option value="${i}"${m.own?.index===i?' selected':''}>${esc(chancePoint(i))}</option>`).join('')}</select><div class="cl-actions">${button('clear','Clear my pin','',m.own?'':'disabled')}${button('reference',m.reference?'Hide reference':'Show reference','',`aria-pressed="${!!m.reference}"`)}</div>${!m.own?'<p data-cl-no-pin>Your pin is not placed yet.</p>':''}${line(rows)}</section></div><p class="cl-rule">${esc(chanceCopy.rule)}</p><p>${esc(chanceCopy.marks)}</p>`;}
function learn(work){const lesson=chanceLessons[work.lesson],bags=lesson.bags.map(i=>chanceBags[i]),rows=bags.map(b=>{const index=12*b.sun/(b.sun+b.moon),raw=`${b.sun}/${b.sun+b.moon}`,reduced=chancePoint(index).split(' = ').at(-1);return {kind:'reference',index,label:`${bagName(b)}: ${raw}${raw===reduced?'':` = ${reduced}`}`};});return `<p>${esc(chanceCopy.learnInstruction)}</p>${turnControls('lesson',work.lesson,chanceLessons.length,'picture')}<h3 id="cl-lesson" tabindex="-1">${esc(lesson.title)}</h3><p class="cl-teaching">${esc(lesson.text)}</p><div class="cl-lesson-bags">${bags.map(bagPicture).join('')}</div>${line(rows)}`;}
function questions(work,m){const q=chanceQuestions[work.question];return `<p>${esc(chanceCopy.questionsInstruction)}</p>${turnControls('question',work.question,chanceQuestions.length,'question')}<h3 id="cl-question" tabindex="-1">${esc(q.prompt)}</h3><div class="cl-choices">${q.choices.map((c,i)=>button('answer',c.label,i,`aria-pressed="${m.selected===i}"`)).join('')}</div>${m.feedback?`<p class="cl-feedback" role="status" data-cl-feedback>${esc(m.feedback)}</p>`:''}${button('explanation',m.explanation?'Hide explanation':'Show explanation','',`aria-expanded="${!!m.explanation}"`)}${m.explanation?`<p class="cl-feedback" data-cl-explanation>${esc(m.explanation)}</p>`:''}`;}
export function chanceLinePage(work){const m=chanceLineModel(work),pageIndex=pages.findIndex(([p])=>p===work.page),title=pages[pageIndex][1];return `<div class="cl-page" data-cl-root><header><div class="cl-actions">${button('back','Back to Seed Stall')}${hearButton(chanceLineNarration(work),'Hear this page').replace('data-speak=', 'data-cl-hear data-speak=')}</div><p class="cl-kicker">The orchard sign bench</p><h1 id="cl-title" tabindex="-1">Chance Line</h1><p>Make a chance sign for orchard visitors. A chance is not a promise about the next draw.</p></header><nav class="cl-pages" aria-label="Chance Line pages">${pages.map(([p,t])=>button('page',t,p,`aria-current="${p===work.page?'page':'false'}"`)).join('')}</nav><section class="cl-sheet"><h2 id="cl-page-title" tabindex="-1">${esc(title)}</h2>${work.page==='build'?build(work,m):work.page==='learn'?learn(work):questions(work,m)}</section><nav class="cl-actions cl-page-turns" aria-label="Previous or next page">${button('page','Previous page',pages[Math.max(0,pageIndex-1)][0],pageIndex===0?'disabled':'')}${button('page','Next page',pages[Math.min(2,pageIndex+1)][0],pageIndex===2?'disabled':'')}</nav><div class="cl-lifetime"><p>${esc(chanceCopy.lifetime)}</p></div></div>`;}
export function bindChanceLine(work,ctx){const root=document.querySelector('[data-cl-root]');if(!root)return;
 const valid=(control,e)=>{if(ctx.live(control)&&!control.disabled)return true;e.preventDefault();e.stopImmediatePropagation();return false;};
 const act=(n,e)=>{if(!valid(n,e))return;ctx.stopSpeech?.();ctx.stopSound?.();if(n.matches('[data-cl-hear]')){n.dataset.speak=chanceLineNarration(work);return;}e.preventDefault();const action=n.dataset.clAction;if(action==='back'){ctx.back();return;}let value=n.matches('select')?n.value:n.dataset.clValue;if(['bag','pin','lesson','question','answer'].includes(action)){if(value==='')return;value=Number(value);}const next=changeChanceLine(work,action,value);if(next===work)return;ctx.change(next);ctx.render();let focus=action==='page'?'#cl-page-title':action==='lesson'?'#cl-lesson':action==='question'?'#cl-question':['pin','clear'].includes(action)?'#cl-point-select':action==='bag'&&(n.matches('select')||value===0||value===chanceBags.length-1)?'#cl-bag-select':`[data-cl-action="${action}"][data-cl-value="${CSS.escape(n.dataset.clValue)}"]`;ctx.focus?.(focus);};
 root.querySelectorAll('button,select').forEach(n=>{n.addEventListener('click',e=>{if(n.matches('select')){valid(n,e);return;}act(n,e);},{capture:true});if(n.matches('select'))n.addEventListener('change',e=>act(n,e),{capture:true});});
}
